def road(name,x0,x1,y0,y1):
    nx=max(2,int((x1-x0)*3)); ny=max(2,int((y1-y0)*3)); v=[]; f=[]
    for j in range(ny+1):
        y=y0+(y1-y0)*j/ny
        for i in range(nx+1):
            x=x0+(x1-x0)*i/nx; v.append((x,y,height(x,y)+.025))
    for j in range(ny):
        for i in range(nx):
            k=j*(nx+1)+i; f.append((k,k+1,k+nx+2,k+nx+1))
    mesh(name,v,f,gravel)
